#include <algorithm>
#include <array>
#include <fstream>
#include <limits>
#include <vector>
using Rectangle = std::array<long long, 4>;
bool inside(const Rectangle &r, long long doubledX, long long doubledY) {
    return 2 * r[0] < doubledX && doubledX < 2 * r[2]
        && 2 * r[1] < doubledY && doubledY < 2 * r[3];
}
int main() {
    std::ifstream in("billboard.in");
    std::ofstream out("billboard.out");
    std::array<Rectangle, 2> rectangles;
    std::vector<long long> xs, ys;
    for (auto &r : rectangles) {
        for (auto &coordinate : r) in >> coordinate;
        xs.push_back(r[0]); xs.push_back(r[2]);
        ys.push_back(r[1]); ys.push_back(r[3]);
    }
    std::sort(xs.begin(), xs.end());
    xs.erase(std::unique(xs.begin(), xs.end()), xs.end());
    std::sort(ys.begin(), ys.end());
    ys.erase(std::unique(ys.begin(), ys.end()), ys.end());
    long long left = std::numeric_limits<long long>::max();
    long long bottom = left, right = -left, top = -left;
    bool any = false;
    for (std::size_t i = 0; i + 1 < xs.size(); ++i) {
        for (std::size_t j = 0; j + 1 < ys.size(); ++j) {
            const long long doubledX = xs[i] + xs[i + 1];
            const long long doubledY = ys[j] + ys[j + 1];
            if (inside(rectangles[0], doubledX, doubledY)
                && !inside(rectangles[1], doubledX, doubledY)) {
                any = true;
                left = std::min(left, xs[i]); right = std::max(right, xs[i + 1]);
                bottom = std::min(bottom, ys[j]); top = std::max(top, ys[j + 1]);
            }
        }
    }
    out << (any ? (right - left) * (top - bottom) : 0) << '\n';
}
