#include <algorithm>
#include <array>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("lifeguards.in");
    std::ofstream out("lifeguards.out");
    int n;
    in >> n;
    std::vector<std::pair<int, int>> shifts(n);
    std::array<int, 1000> count{};
    for (auto &shift : shifts) {
        in >> shift.first >> shift.second;
        for (int t = shift.first; t < shift.second; ++t) ++count[t];
    }
    int total = 0;
    for (int value : count) if (value > 0) ++total;
    int leastLoss = 1000;
    for (const auto &shift : shifts) {
        int loss = 0;
        for (int t = shift.first; t < shift.second; ++t)
            if (count[t] == 1) ++loss;
        leastLoss = std::min(leastLoss, loss);
    }
    out << total - leastLoss << '\n';
}
