#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("outofplace.in");
    std::ofstream out("outofplace.out");
    int n;
    in >> n;
    std::vector<int> heights(n);
    for (int &height : heights) in >> height;
    std::vector<int> ordered = heights;
    std::sort(ordered.begin(), ordered.end());
    int mismatches = 0;
    for (int i = 0; i < n; ++i) if (heights[i] != ordered[i]) ++mismatches;
    out << std::max(0, mismatches - 1) << '\n';
}
